def diff_ways_to_compute(expression):
    memo = {}

    def solve(expr):
        if expr in memo:
            return memo[expr]
        if expr.isdigit():
            memo[expr] = [int(expr)]
            return memo[expr]
        results = []
        for i, ch in enumerate(expr):
            if ch in '+-*':
                left = solve(expr[:i])                 # recursively solve left substring
                right = solve(expr[i+1:])               # recursively solve right substring
                for l in left:
                    for r in right:
                        if ch == '+':
                            results.append(l + r)
                        elif ch == '-':
                            results.append(l - r)
                        else:
                            results.append(l * r)
        memo[expr] = results                             # memoize by substring
        return results

    return solve(expression)

