import java.util.*;

public class Main {
    static Map<String, List<Integer>> memo = new HashMap<>();

    static List<Integer> diffWaysToCompute(String expr) {
        if (memo.containsKey(expr)) return memo.get(expr);
        if (expr.chars().allMatch(Character::isDigit)) {
            List<Integer> single = new ArrayList<>();
            single.add(Integer.parseInt(expr));
            memo.put(expr, single);
            return single;
        }
        List<Integer> results = new ArrayList<>();
        for (int i = 0; i < expr.length(); i++) {
            char c = expr.charAt(i);
            if (c == '+' || c == '-' || c == '*') {
                List<Integer> left = diffWaysToCompute(expr.substring(0, i));    // left substring
                List<Integer> right = diffWaysToCompute(expr.substring(i + 1));  // right substring
                for (int l : left) {
                    for (int r : right) {
                        if (c == '+') results.add(l + r);
                        else if (c == '-') results.add(l - r);
                        else results.add(l * r);
                    }
                }
            }
        }
        memo.put(expr, results);                                                 // memoize by substring
        return results;
    }
}

