#include <bits/stdc++.h>
using namespace std;

unordered_map<string, vector<int>> memo;

vector<int> diffWaysToCompute(string expr) {
    if (memo.count(expr)) return memo[expr];
    bool allDigits = all_of(expr.begin(), expr.end(), ::isdigit);
    if (allDigits) {
        memo[expr] = {stoi(expr)};
        return memo[expr];
    }
    vector<int> results;
    for (int i = 0; i < (int)expr.size(); i++) {
        char c = expr[i];
        if (c == '+' || c == '-' || c == '*') {
            vector<int> left = diffWaysToCompute(expr.substr(0, i));       // left substring
            vector<int> right = diffWaysToCompute(expr.substr(i + 1));      // right substring
            for (int l : left) {
                for (int r : right) {
                    if (c == '+') results.push_back(l + r);
                    else if (c == '-') results.push_back(l - r);
                    else results.push_back(l * r);
                }
            }
        }
    }
    memo[expr] = results;                                                    // memoize by substring
    return results;
}
